WITH valid AS (SELECT *, CASE WHEN is_remote THEN 'Yes' ELSE 'No' END AS is_remote_label FROM employees WHERE hire_date > DATE '2023-04-30' AND job_title IS NOT NULL), scored AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, is_remote_label, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY manager_id ORDER BY hire_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, SUM(salary) OVER (PARTITION BY dept_id ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, LAG(salary, 2) OVER (PARTITION BY job_title ORDER BY hire_date ASC, id ASC) AS prev_salary, DENSE_RANK() OVER (PARTITION BY level ORDER BY salary ASC) AS salary_dense_rank, AVG(salary) OVER (ORDER BY salary ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS salary_avg_2 FROM valid), with_windows AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, is_remote_label, first_known_job_title, cumulative_salary, prev_salary, salary_dense_rank, salary_avg_2, ROUND(salary_dense_rank / SUM(salary_dense_rank) OVER (PARTITION BY job_title), 4) AS salary_dense_rank_share, CUME_DIST() OVER (PARTITION BY job_title ORDER BY salary DESC) AS salary_cume_dist, AVG(salary) OVER (PARTITION BY job_title ORDER BY cumulative_salary ASC, id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS salary_avg_6_prior FROM scored) SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, ROUND(AVG(salary_avg_2), 2) AS avg_salary_avg_2, COUNT(*) FILTER (WHERE level = 'L4') AS l4_rows, SIZE(COLLECT_SET(job_title)) AS num_job_titles FROM with_windows GROUP BY DATE_TRUNC('MONTH', hire_date) ORDER BY l4_rows DESC
